package api.auth.kimdeo.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
data class ResponseMessage<T>(
    val data: T? = null,
    val message: String,
    val errorMessage: String = "",
    val status: Boolean
)


@Serializable
data class EmailVerifyModel(
    val email: String,
    @SerialName("format_valid")
    var formatValid: Boolean,
    @SerialName("mx_found")
    var mxFound: Boolean,
    @SerialName("smtp_check")
    var smtpCheck: Boolean,
    val disposable: Boolean,
    val free: Boolean,
    val score: Double,
)