@Composable
fun HorizontalTextIcon(
    modifier: Modifier = Modifier,
    text: String,
    style: TextStyle = LocalTextStyle.current,
    maxLines: Int = Int.MAX_VALUE,
    overflow: TextOverflow = TextOverflow.Clip,
    horizontalArrangement: Arrangement.Horizontal = Arrangement.Start,
    leadingContent: (@Composable () -> Unit)? = null,
    trailingContent: (@Composable () -> Unit)? = null,
) {
    Row(
        modifier = modifier,
        horizontalArrangement = horizontalArrangement,
        verticalAlignment = Alignment.CenterVertically
    ) {
        leadingContent?.invoke()
        Text(text, style = style, maxLines = maxLines, overflow = overflow)
        trailingContent?.invoke()

    }
}

@Composable
fun VerticalTextIcon(
    modifier: Modifier = Modifier,
    text: String,
    style: TextStyle = LocalTextStyle.current,
    maxLines: Int = Int.MAX_VALUE,
    overflow: TextOverflow = TextOverflow.Clip,
    verticalArrangement: Arrangement.Vertical = Arrangement.Top,
    horizontalAlignment: Alignment.Horizontal = Alignment.Start,
    leadingContent: (@Composable () -> Unit)? = null,
    trailingContent: (@Composable () -> Unit)? = null,
) {
    Column(
        modifier = modifier,
        horizontalAlignment = horizontalAlignment,
        verticalArrangement = verticalArrangement
    ) {
        leadingContent?.invoke()
        Text(text, style = style, maxLines = maxLines, overflow = overflow)
        trailingContent?.invoke()

    }
}


@Composable
fun StyledText(
    modifier: Modifier = Modifier,
    maxLines: Int = Int.MAX_VALUE,
    overflow: TextOverflow = TextOverflow.Clip,
    contents: List<ComTextModel>
) {
    val uriHandler = LocalUriHandler.current
    val annotatedText = remember(contents) {
        buildAnnotatedString {
            contents.forEach { item ->
                if (item.urlLink == null) {
                    withStyle(item.style) { append(item.text) }
                } else {
                    val link =
                        LinkAnnotation.Url(
                            item.urlLink,
                            TextLinkStyles(
                                item.style.copy(
                                    textDecoration = TextDecoration.Underline
                                )
                            ),
                        ) {
                            val url = (it as LinkAnnotation.Url).url
                            // log some metrics
                            uriHandler.openUri(url)
                        }
                    withLink(link) { append(item.text) }
//                    add underline
                }
            }
        }
    }
    Text(
        modifier = modifier,
        text = annotatedText,
        maxLines = maxLines,
        overflow = overflow
    )
}


@Composable
fun DisplayToast(
    show: Boolean,
    onDismiss: () -> Unit,
    alignment: Alignment = Alignment.Center,
    durationSeconds: Long = 3,
    content: @Composable (Long) -> Unit
) {
    var visible by mutableStateOf(show)
    // Auto-dismiss timer
    LaunchedEffect(visible) {
        if (visible) {
            delay(durationSeconds * 1000L)
            visible = false
            onDismiss()
        }
    }
    if (visible) {
        Popup(
            alignment = alignment,
            onDismissRequest = { onDismiss() }
        ) { content(durationSeconds) }
    }
}

@Composable
fun DisplayPopup(
    show: Boolean,
    onDismiss: () -> Unit,
    contentAlignment: Alignment = Alignment.Center,
    content: @Composable () -> Unit
) {
    if (show) {
        Popup(
            alignment = contentAlignment,
            onDismissRequest = { onDismiss() }
        ) { content() }
    }
}


@Composable
fun <T> DisplayExpandableHorizontal(
    modifier: Modifier = Modifier,
    enable: Boolean = true,
    onExpand: (() -> Unit)? = null,
    onItemClicked: ((T) -> Unit)? = null,
    items: List<T>,
    itemContent: @Composable (T) -> Unit,
    hAlignment: Alignment.Horizontal = Alignment.CenterHorizontally,
    content: @Composable () -> Unit
) {
    val isExpanded = remember { mutableStateOf(false) }
    Column(
        modifier = Modifier.clickable(
            onClick = {
                isExpanded.value = !isExpanded.value

                onExpand?.invoke()
            },
        ).then(modifier),
        horizontalAlignment = hAlignment
    ) {
        content()
        if (isExpanded.value && enable) {
//            FlowRow { items.forEach { item -> Box(Modifier.weight(1f), Alignment.Center) { itemContent(item) } } }
            FlowRow(
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
            ) {
                items.forEach { item ->
                    Box(
                        Modifier.clickable(
                            onClick = {
                                isExpanded.value = !isExpanded.value
                                onItemClicked?.invoke(item)
                            },
                            enabled = onItemClicked != null
                        ), content = { itemContent(item) })
                }
            }
        }
    }
}


@Composable
fun DisplayDropDown(
    modifier: Modifier = Modifier,
    contentAlignment: Alignment = Alignment.Center,
    onExpand: () -> Unit = {},
    // Use a ColumnScope extension for more idiomatic DSL-like usage
    dropdownContent: @Composable ColumnScope.(onDismiss: () -> Unit) -> Unit,
    anchorContent: @Composable () -> Unit
) {
    // Use 'by' property delegate for cleaner syntax
    var isExpanded by rememberSaveable { mutableStateOf(false) }
    Box(
        modifier = modifier,
        contentAlignment = contentAlignment
    ) {
        Box(
            modifier = Modifier.clickable {
                if (!isExpanded) {
                    isExpanded = true
                    onExpand()
                } else {
                    isExpanded = false
                }
            },
        ) {
            anchorContent()
        }
        // Adjust percentage as needed
        DropdownMenu(
            expanded = isExpanded,
            onDismissRequest = { isExpanded = false }
        ) {
            // We pass the toggle back to the items so they can close the menu when clicked
            dropdownContent { isExpanded = false }
        }
    }
}


@OptIn(ExperimentalMaterial3Api::class, ExperimentalMaterial3Api::class)
@Composable
fun DisplayBottomSheet(
    modifier: Modifier = Modifier,
    onExpand: () -> Unit = {},
    sheetContent: @Composable ColumnScope.(onDismiss: () -> Unit) -> Unit,
    anchorContent: @Composable () -> Unit
) {
    var showSheet by rememberSaveable { mutableStateOf(false) }

    val sheetState = rememberModalBottomSheetState(
        skipPartiallyExpanded = true
    )

    // Anchor (your clickable UI)
    Box(
        modifier = Modifier.clickable {
            showSheet = true
            onExpand()
        }
    ) {
        anchorContent()
    }

    // Bottom Sheet
    if (showSheet) {
        ModalBottomSheet(
            modifier = modifier,
            onDismissRequest = { showSheet = false },
            sheetState = sheetState
        ) {
            sheetContent { showSheet = false }
        }
    }
}

@Composable
fun DisplayExpandableVertical(
    modifier: Modifier,
    onExpand: () -> Unit = {},
    contents: List<String>,
    style: TextStyle = MaterialTheme.typography.bodyMedium,
    imageVectorOpen: ImageVector?,
    imageVectorClose: ImageVector?,
    text: String?
) {
    val isExpanded = remember { mutableStateOf(false) }


    Column(
        modifier = Modifier.clickable(
            onClick = {
                isExpanded.value = !isExpanded.value; onExpand()
            }).then(modifier),
        verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
    ) {
        HorizontalTextIcon(
            leadingContent = {
                if (imageVectorOpen != null && imageVectorClose != null) Icon(
                    imageVector = if (isExpanded.value) imageVectorOpen else imageVectorClose,
                    contentDescription = text
                )
            },
            horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
            text = text!!,
            style = style
        )
        if (isExpanded.value) {
            contents.forEach { dmi -> Text(text = dmi, style = style) }
        }
    }
}

