@Composable
fun SelectLanguages(
    selectedKimLanguage: String,
//    screenModel: KimdeoPlayerScreenModel,
    kimLanguage: KimLanguage,
    kimLanguages: List<KimLanguage>,
    onLangNalChanged: (String) -> Unit,
    onClear: () -> Unit,
    onSelect: (KimLanguage) -> Unit
) {
    Column {
        TextField(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = PixelDensity.SMALL)
                .clip(MaterialTheme.shapes.medium),

            value = selectedKimLanguage,
            onValueChange = onLangNalChanged,
            textStyle = MaterialTheme.typography.bodyMedium.copy(
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            ),
            placeholder = {
                Text("Search language...")
            },

            singleLine = true,

            leadingIcon = {
                Icon(
                    imageVector = TablerIcons.Search,
                    contentDescription = "Search"
                )
            },

            trailingIcon = {
                if (selectedKimLanguage.isNotEmpty()) {
                    IconButton(onClick = onClear) {
                        Icon(
                            imageVector = TablerIcons.ClearAll,
                            contentDescription = "Clear"
                        )
                    }
                }
            },

            shape = MaterialTheme.shapes.medium,

            colors = TextFieldDefaults.colors(
                focusedContainerColor = MaterialTheme.colorScheme.surface,
                unfocusedContainerColor = MaterialTheme.colorScheme.surfaceVariant,
                focusedIndicatorColor = MaterialTheme.colorScheme.primary,
                unfocusedIndicatorColor = MaterialTheme.colorScheme.outline,
                cursorColor = MaterialTheme.colorScheme.primary
            )
        )

        FlowRow(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            maxItemsInEachRow = 3,
        ) {
            kimLanguages.forEach { item ->

                val isSelected = kimLanguage == item
//                item.codeCountry

                Surface(
                    modifier = Modifier
                        .padding(PixelDensity.SMALL)
                        .clip(MaterialTheme.shapes.medium)
                        .clickable(onClick = { onSelect(item) }),
                    shape = MaterialTheme.shapes.medium,
                    color = if (isSelected)
                        MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                    else
                        MaterialTheme.colorScheme.surfaceVariant,
                    tonalElevation = if (isSelected) 4.dp else 1.dp,
                    border = BorderStroke(
                        width = 1.dp,
                        color = if (isSelected)
                            MaterialTheme.colorScheme.primary
                        else
                            MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)
                    )
                ) {
                    Row(
                        modifier = Modifier.padding(PixelDensity.SMALL),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                    ) {
                        SubcomposeAsyncImage(
                            model = KimLanguage.getCountryImageUrl(item.codeCountry),
                            contentDescription = "country image",
//                                onError = {Logger.e { it.result.throwable.toString() }}
                            loading = {
                                CircularProgressIndicator(
                                    Modifier.size(
                                        PixelDensity.LARGE
                                    )
                                )
                            },
                            error = { Icon(TablerIcons.World, null) }
                        )

                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text(
                                text = item.name.replaceFirstChar {
                                    if (it.isLowerCase()) it.titlecase() else it.toString()
                                },
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontWeight = FontWeight.SemiBold
                                ),
                                color = if (isSelected)
                                    MaterialTheme.colorScheme.primary
                                else
                                    MaterialTheme.colorScheme.onSurface
                            )

                            Spacer(modifier = Modifier.height(2.dp))

                            Text(
                                text = item.codeCountry.uppercase(),
                                style = MaterialTheme.typography.labelSmall,
                                color = if (isSelected)
                                    MaterialTheme.colorScheme.primary
                                else
                                    MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                }
            }
            Text(
                modifier = Modifier
                    .padding(horizontal = PixelDensity.LARGE)
                    .outline(
                        width = PixelDensity.VERY_SMALL,
                        padding = PixelDensity.SMALL
                    ),
                text = "...",
                style = MaterialTheme.typography.headlineMedium
            )
        }
    }
}


@Composable
fun VolumeOverlay(
    volume: Float,
    onVolumeChange: (Float) -> Unit,
    modifier: Modifier = Modifier,
    maxVolume: Float = 1f,
) {

    var dragAmount by remember {
        mutableFloatStateOf(0f)
    }

    Box(
        modifier = modifier
            .fillMaxHeight()
            .pointerInput(Unit) {

                detectVerticalDragGestures(

                    onVerticalDrag = { _, dragY ->

                        dragAmount += dragY

                        val sensitivity = 600f

                        val delta = -(dragAmount / sensitivity)

                        val newVolume = (volume + delta)
                            .coerceIn(0f, maxVolume)

                        onVolumeChange(newVolume)

                        dragAmount = 0f
                    }
                )
            }
    ) {

        AnimatedVisibility(
            visible = true,
            modifier = Modifier
                .align(Alignment.CenterEnd)
                .padding(end = 24.dp)
        ) {

            Card(
                shape = MaterialTheme.shapes.medium
            ) {

                Column(
                    modifier = Modifier
                        .padding(
                            horizontal = 16.dp,
                            vertical = 24.dp
                        ),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {

                    Icon(
                        imageVector = when {
                            volume == 0f -> TablerIcons.Volume3
                            volume < 0.5f -> TablerIcons.Volume2
                            else -> TablerIcons.Volume
                        },
                        contentDescription = null
                    )

                    Spacer(Modifier.height(16.dp))

                    LinearProgressIndicator(
                        progress = { volume / maxVolume },
                        modifier = Modifier
                            .height(120.dp)
                            .width(8.dp)
                            .rotate(270f)
                    )

                    Spacer(Modifier.height(12.dp))

                    Text(
                        text = "${(volume * 100).toInt()}%"
                    )
                }
            }
        }
    }
}


@Composable
fun VolumeControlOverlay(
    modifier: Modifier = Modifier,
    initialVolume: Float = 0.5f,
    onVolumeChanged: (Float) -> Unit
) {
    var volume by remember { mutableStateOf(initialVolume) }

    // Logic to select the right icon based on volume level
    val icon = when {
        volume == 0f -> TablerIcons.Volume3
        volume < 0.5f -> TablerIcons.Volume2
        else -> TablerIcons.Volume
    }

    Box(
        modifier = modifier,
        contentAlignment = Alignment.Center
    ) {
        Row(
            modifier = Modifier
                .background(
                    color = Color.Black.copy(alpha = 0.6f),
                    shape = RoundedCornerShape(24.dp)
                )
                .padding(horizontal = 16.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Icon(
                imageVector = icon,
                contentDescription = "Volume",
                tint = Color.White,
                modifier = Modifier.size(24.dp)
            )

            Slider(
                value = volume,
                onValueChange = { newValue ->
                    volume = newValue
                    onVolumeChanged(newValue)
                },
                valueRange = 0f..1f,
                modifier = Modifier.width(200.dp), // Fixed width like a phone overlay
                colors = SliderDefaults.colors(
                    thumbColor = Color.White,
                    activeTrackColor = Color.White,
                    inactiveTrackColor = Color.White.copy(alpha = 0.3f)
                )
            )

            // Optional Percentage Text
            Text(
                text = "${(volume * 100).toInt()}%",
                color = Color.White,
                style = MaterialTheme.typography.bodySmall,
                modifier = Modifier.width(32.dp)
            )
        }
    }
}


@Composable
fun VolumeControl(
    modifier: Modifier = Modifier,
    initialVolume: Float = 0.5f,
    onVolumeChanged: (Float) -> Unit = {}
) {
    var volume by remember { mutableStateOf(initialVolume) }
    var showIndicator by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val step = 0.05f

    fun changeVolume(delta: Float) {
        val newVolume = (volume + delta).coerceIn(0f, 1f)
        volume = newVolume
        onVolumeChanged(newVolume)

        // Show volume indicator temporarily
        scope.launch {
            showIndicator = true
            delay(1500)
            showIndicator = false
        }
    }

    Box(
        modifier = modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        // Volume indicator overlay
        if (showIndicator) {
            Surface(
                modifier = Modifier
                    .wrapContentSize()
                    .padding(16.dp),
                shape = RoundedCornerShape(8.dp),
                color = Color.Magenta.copy(alpha = 0.8f)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Volume icon
                    Icon(
                        imageVector = when {
                            volume == 0f -> TablerIcons.Volume3
                            volume < 0.5f -> TablerIcons.Volume2
                            else -> TablerIcons.Volume
                        },
                        contentDescription = "Volume",
                        tint = Color.Green,
                        modifier = Modifier.size(32.dp)
                    )

                    Spacer(modifier = Modifier.height(8.dp))

                    // Progress bar
                    LinearProgressIndicator(
                        progress = { volume },
                        modifier = Modifier
                            .width(120.dp)
                            .height(4.dp),
                        color = Color.Yellow,
                        trackColor = Color.Blue,
                        strokeCap = ProgressIndicatorDefaults.LinearStrokeCap,
                    )

                    Spacer(modifier = Modifier.height(4.dp))

                    // Volume percentage
                    Text(
                        text = "${(volume * 100).toInt()}%",
                        color = Color.Red,
                        fontSize = 12.sp
                    )
                }
            }
        }

        // Control buttons
        Row(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Decrease volume button
            IconButton(
                onClick = { changeVolume(-step) },
                modifier = Modifier
                    .background(
                        Color.Black.copy(alpha = 0.6f),
                        CircleShape
                    )
                    .size(48.dp)
            ) {
                Icon(
                    imageVector = TablerIcons.ArrowBarDown,
                    contentDescription = "Decrease Volume",
                    tint = Color.White
                )
            }

            // Increase volume button
            IconButton(
                onClick = { changeVolume(step) },
                modifier = Modifier
                    .background(
                        Color.Black.copy(alpha = 0.6f),
                        CircleShape
                    )
                    .size(48.dp)
            ) {
                Icon(
                    imageVector = TablerIcons.ArrowBarUp,
                    contentDescription = "Increase Volume",
                    tint = Color.White
                )
            }
        }
    }
}


@Composable
fun GradientIcon(
    modifier: Modifier = Modifier,
    imageVector: ImageVector,
    gradientColors: List<Color> = listOf(Color(0xFF9F5CFF), Color(0xFFF0A966))
) {
    // 1. Create your brush (e.g., linear, vertical, or radial)
    val gradientBrush = Brush.linearGradient(colors = gradientColors)

    Icon(
        imageVector = imageVector,
        contentDescription = "Favorite Icon",
        // 2. Clear default tint so it does not override your gradient
        tint = Color.Unspecified,
        modifier = modifier.then(
            Modifier
                // 3. Render offscreen to cleanly mask the gradient to the icon
                .graphicsLayer(compositingStrategy = androidx.compose.ui.graphics.CompositingStrategy.Offscreen)
                // 4. Draw the icon content, then apply the brush over it
                .drawWithContent {
                    drawContent()
                    drawRect(
                        brush = gradientBrush,
                        blendMode = BlendMode.SrcIn
                    )
                }
        )
    )
}

@Composable
fun ResetReloadButton(
    imageVector: ImageVector,
    color: Color,
    onClicked: () -> Unit
) {
    var isResetting by remember { mutableStateOf(false) }
    val infiniteTransition = rememberInfiniteTransition()

    // Continuous rotation while resetting
    val rotation by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = LinearEasing)
        )
    )

    // Reset rotation when not resetting
    val displayRotation = if (isResetting) rotation else 0f

    IconButton(
        onClick = {
            if (!isResetting) {
                isResetting = true
                onClicked()
                isResetting = false
            }
        },
        content = {
            Icon(
                imageVector,
                null,
                modifier = Modifier.rotate(displayRotation),
                tint = color
            )
        }
    )
}