    fun initializeScreenModel() {
        connectionState = ConnectionState.OnLoading
        screenModelScope.launch(Dispatchers.Main) {
            if (userToken == null) {
                connectionState = ConnectionState.OnFailure("You are not logged in, please login to continue")
            } else {
                val res = ApiActions.getUserModelByEmail(userToken.email)
                if (res.data == null) {
                    connectionState = ConnectionState.OnFailure("You are not logged in, please login to continue")
                    return@launch
                }
                connectionState = ConnectionState.OnSucsess("")
                userModel = res.data
                try {
                    if (transcribeJobModel != null) {
                        ApiActionsWebsocket.connectToWebsocket(
                            transcribeJobModel!!.transcriptionId,
                            userModel?.apiKey!!,
                            onConnect = {
                                transcribeJobModel = it
                            }
                        )
                    }
                } catch (e: Exception) {
                    delay(3000)
                }
            }
        }
    }

    fun checkKimLanguages(lang: String) {
        if (lang.isBlank()) {
            _kimLanguages.clear()
            _kimLanguages.addAll(KimLanguage.entries.shuffled().take(5))
            return
        }
        // 1. Calculate the new data first
        val filtered = KimLanguage.entries
            .filter {
                val name = it.name.lowercase()
                name.contains(lang.lowercase(), ignoreCase = true)
            }
            .shuffled()
            .take(5)

        // 2. Update the existing SnapshotStateList
        _kimLanguages.clear()
        _kimLanguages.addAll(filtered)
    }

    fun changeTranscriptionScreenConfigureType(tsct: TranscriptionScreenConfigureType) {
        transcriptionScreenConfigureType =
            if (tsct == transcriptionScreenConfigureType) TranscriptionScreenConfigureType.NONE
            else tsct
