    fun transcribeMediaFile() {
        screenModelScope.launch(Dispatchers.Main) {
            runCatching {
                ApiActions.getTextFromLocal(
                    FromLocalMediaModel(
                        email = userModel!!.email,
                        filePath = transcribeJobModel!!.filePath,
                        jobId = transcribeJobModel!!.transcriptionId,
                        languageCode = kimLanguage.codeCountry,
                        addWordTimestamp = useWordTimeStamp,
                        hasMultilingual = useMultiLingual,
                        bgVolume = bgVolume / 10
                    )
                )
            }.onSuccess { response ->
                transcribeJobModel = response.data
                transcribingScreenPopup = PopupModel(
                    show = true,
                    title = "Transcription",
                    description = response.message,
                    content = {
                        if (response.data != null)
                            Icon(TablerIcons.Check, null, tint = Color.Green)
                        else
                            Icon(TablerIcons.AlertTriangle, null, tint = Color.Red)
                    }
                )
                toastPopup = PopupModel(
                    show = true,
                    title = "Upload Success",
                    description = "This session will be charged ${Credits.textFromMedia(transcribeJobModel?.numOfWords)} credits",
                    content = { Icon(TablerIcons.CreditCard, null, tint = Color.Blue) }
                )
            }.onFailure { error ->
                transcribingScreenPopup = PopupModel(
                    show = true,
                    title = "Error Transcribing",
                    description = "There was an error transcribing Media File ${error.message}",
                    content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                )
            }
        }
    }

    fun uploadCreateJob() {
        screenModelScope.launch(Dispatchers.Main) {
            fileUploadState = FileConnectionState.OnUploading
            //*****************************************************************************************
            transcribeJobModel = null
            val fileBytes = platformFile?.size()
            runCatching {
                ApiActions.createAJob(
                    email = userModel!!.email,
                    fileName = platformFile!!.name,
                    bytes = platformFile!!.readBytes(),
                    mimeType = platformFile?.mimeType()?.toString() ?: "application/octet-stream",
                    onProgress = { sentByte ->
                        transcribeProcess = if (fileBytes == null) Triple(0f, "", "")
                        else Triple(
                            fileBytes.toPercentage(sentByte).toFloat(),
                            "uploading file ${
                                Tools.convertLongToReadableSize(sentByte).replace("b", "%")
                            } of ${
                                Tools.convertLongToReadableSize(platformFile!!.size())
                            }",
                            ""
                        )
                    },
                )
            }
                .onSuccess { response ->
                    if (response.data != null) {
                        transcribeJobModel = response.data
                        ApiActionsWebsocket.connectToWebsocket(
                            response.data.transcriptionId,
                            userModel?.apiKey!!,
                            onConnect = {
                                transcribeJobModel = it
                            }
                        )
                        fileUploadState = FileConnectionState.OnSuccess("")
                        transcribingScreenPopup = PopupModel(
                            show = true,
                            title = "File Upload",
                            description = response.message,
                            content = {
                                if (!response.status)
                                    Icon(TablerIcons.AlertTriangle, null, tint = Color.Red)
                                else
                                    Icon(TablerIcons.Check, null, tint = Color.Green)
                            }
                        )
                        toastPopup = PopupModel(
                            show = true,
                            title = "Upload Success",
                            description = "This session will be charged ${Credits.CREATE_JOB_CREDITS} credits",
                            content = { Icon(TablerIcons.CreditCard, null, tint = Color.Blue) }
                        )
                    }
                }
                .onFailure { error ->
                    fileUploadState = FileConnectionState.OnFailure("Error uploading file $error")
                    transcribingScreenPopup = PopupModel(
                        show = true,
                        title = "Error Transcribing Media File",
                        description = "There was an error transcribing Media File $error",
                        content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                    )
                }
            //*****************************************************************************************
        }
    }

