enum class PlaygroundState {
    PLAYGROUND_PLAYER, PLAYGROUND_SELECT
}

class PlaygroundScreenModel : ScreenModel {
    override fun onDispose() {
        audioPlayerDisposable?.dispose()
        CoroutineScope(Dispatchers.Default).launch {
            try {
                if (delFilePath.isNotEmpty()) ApiActionsFile.deleteSpecificFilesFree(delFilePath)
//                ApiActionsFile.deleteSpecificFilesFree(listOf("uploads/playground/794066wW3r/1781010379.wav"))
            } catch (e: Exception) {
                Logger.e { "Clean up Exception" }
            }
        }
        super.onDispose()
    }

    var playgroundState by mutableStateOf(PlaygroundState.PLAYGROUND_SELECT)
    var fileByteArray by mutableStateOf<ByteArray?>(null)
    var audioByteArray by mutableStateOf<ByteArray?>(null)
    var audioPlayerDisposable: Disposable? = null

    var platformFile by mutableStateOf<PlatformFile?>(null)
    var kimLanguage by mutableStateOf(KimLanguage.ENGLISH)
    var fileUploadState by mutableStateOf<FileConnectionState>(FileConnectionState.None)
    var transcribeProcess by mutableStateOf(Triple(0f, "", ""))
    var videoController: VideoInteraction? = null
        private set
    var audioController: AudioInteraction? = null
        private set
    var audioFilePath: FilePathModel? = null
    var lastSeekTime = 0.0

    private val delFilePath = mutableListOf<String>()

    private var _kimLanguages =
        mutableStateListOf<KimLanguage>().apply { addAll(KimLanguage.entries.shuffled().take(5)) }
    val kimLanguages: List<KimLanguage> get() = _kimLanguages
    var playgroundPopup by mutableStateOf(PopupModel())
    var deleteFolderUid = ""
    var enableButton by mutableStateOf(true)
        private set
    var playgroundStateConnectionState by mutableStateOf<ConnectionState>(ConnectionState.None)

    fun resetPlayGroundScreenModel() {
        screenModelScope.launch {
            playgroundStateConnectionState = ConnectionState.OnLoading

            playgroundState = PlaygroundState.PLAYGROUND_SELECT
            fileByteArray = null
            audioByteArray = null
            audioPlayerDisposable = null
            platformFile = null
            kimLanguage = KimLanguage.ENGLISH
            fileUploadState = FileConnectionState.None
            transcribeProcess = Triple(0f, "", "")
            videoController = null
            audioController = null
            audioFilePath = null
            lastSeekTime = 0.0

            delFilePath.clear()
            _kimLanguages =
                mutableStateListOf<KimLanguage>().apply {
                    addAll(
                        KimLanguage.entries.shuffled().take(5)
                    )
                }
            playgroundPopup = PopupModel()
            deleteFolderUid = ""
            enableButton = true

            playgroundStateConnectionState = ConnectionState.OnSucsess("Reset completed")
        }
    }

    fun getMediaFile() {
        screenModelScope.launch(Dispatchers.Main) {
            platformFile = FileKit.openFilePicker(
                mode = FileKitMode.Single,
                type = FileKitType.File(ExportVideoFormat.entries.map { it.name.lowercase() }
                    .toSet())
            )
            if (platformFile != null) {
                val fileSize = Tools.convertLongToMb((platformFile as PlatformFile).size())
                if (fileSize >= 10.0) {
                    playgroundPopup = PopupModel(
                        show = true,
                        content = {
                            Icon(
                                TablerIcons.FileAlert,
                                contentDescription = null,
                                tint = Color.Red
                            )
                        },
                        title = "File Size Error",
                        description = "Your file size is can not be more than 10mb long"
                    )
                } else {
                    fileByteArray = platformFile?.readBytes()
                }
            } else {
                playgroundPopup = PopupModel(
                    show = true,
                    content = {
                        Icon(
                            TablerIcons.FileAlert,
                            contentDescription = null,
                            tint = Color.Red
                        )
                    },
                    title = "File Error",
                    description = "Please select a valid file"
                )
            }
        }
    }

    fun checkKimLanguages(lang: String) {
        if (lang.isBlank()) {
            _kimLanguages.clear()
            _kimLanguages.addAll(KimLanguage.entries.shuffled().take(5))
            return
        }
        // 1. Calculate the new data first
        val filtered = KimLanguage.entries
            .filter {
                val name = it.name.lowercase()
                name.contains(lang.lowercase(), ignoreCase = true)
            }
            .shuffled()
            .take(5)

        // 2. Update the existing SnapshotStateList
        _kimLanguages.clear()
        _kimLanguages.addAll(filtered)
    }

    fun onWatchVideoClicked() {
        playgroundState = PlaygroundState.PLAYGROUND_PLAYER
    }

    fun transcribeVideo() {
        screenModelScope.launch {
            fileUploadState = FileConnectionState.OnUploading
            val fileBytes = platformFile?.size()
            runCatching {
                enableButton = false
                ApiActionsFile.uploadToPlayGround(
                    fileName = platformFile!!.name,
                    bytes = platformFile!!.readBytes(),
                    folderUid = deleteFolderUid,
                    languageCode = kimLanguage.codeCountry,
                    mimeType = platformFile?.mimeType()?.toString() ?: "application/octet-stream",
                    onProgress = { sentByte ->
                        transcribeProcess = if (fileBytes == null) Triple(0f, "", "")
                        else Triple(
                            fileBytes.toPercentage(sentByte).toFloat(),
                            "uploading file ${
                                Tools.convertLongToReadableSize(sentByte).replace("b", "%")
                            } of ${
                                Tools.convertLongToReadableSize(platformFile!!.size())
                            }",
                            ""
                        )
                    }
                )
            }.onSuccess { response ->
                ApiActionsWebsocket.uploadToPlayGroundWebSocket(
                    jobId = response.wsId,
                    onConnect = { wjm ->
                        Logger.e { "Play ground Web Socket: $wjm" }
                        transcribeProcess = Triple(
                            wjm.completePercent.toFloat(),
                            wjm.message,
                            ""
                        )
                        when (wjm.jobStatus) {
                            JobStatus.COMPLETED -> {
                                enableButton = true
                                audioFilePath = wjm.dataType
                                launch {
                                    audioByteArray = ApiActionsFile.loadFileFree(
                                        wjm.dataType?.filePath,
                                    )
                                    wjm.dataType?.filePath?.let { fp ->
                                        delFilePath.add(fp)
                                        if (deleteFolderUid.isEmpty()) {
                                            deleteFolderUid = fp.split("/").dropLast(1).last()
                                        }
                                    }
                                }
                            }
                            JobStatus.FAILED -> {
                                enableButton = true
                                playgroundPopup = PopupModel(
                                    show = true,
                                    content = {
                                        Icon(
                                            TablerIcons.FileAlert,
                                            contentDescription = null,
                                            tint = Color.Red
                                        )
                                    },
                                    title = "Transcribe Error",
                                    description = wjm.message
                                )
                            }
                            else -> Unit
                        }
                    }
                )
            }.onFailure { error ->
                enableButton = true
                Logger.e { "Play ground transcribe Failure: $error" }
                playgroundPopup = PopupModel(
                    show = true,
                    content = {
                        Icon(
                            TablerIcons.FileAlert,
                            contentDescription = null,
                            tint = Color.Red
                        )
                    },
                    title = "Transcription Error",
                    description = error.message
                        ?: "There was an error transcribing please try again later"
                )

            }
        }
    }

    internal fun onBackPressed(function: () -> Unit) {
        audioController?.stop()
        function()
    }

    fun attachVideoController(
        controller: VideoInteraction
    ) {
        videoController = controller
    }

    fun attachAudioController(
        controller: AudioInteraction
    ) {
        audioController = controller
    }
}