package api.auth.kimdeo.utils

import api.auth.kimdeo.model.UuidStrength
import kotlinx.datetime.TimeZone
import kotlinx.datetime.number
import kotlinx.datetime.toLocalDateTime
import kotlin.math.floor
import kotlin.math.ln
import kotlin.math.pow
import kotlin.time.Clock
import kotlin.time.Instant

object Tools {
    fun getGreetingDataTime(): String {
        val currentMoment = Clock.System.now()
        val datetime = currentMoment.toLocalDateTime(TimeZone.currentSystemDefault())

        val monthName =
            datetime.month.name.replaceFirstChar { if (it.isLowerCase()) it.titlecase() else it.toString() }
        val dayOfWeekName =
            datetime.dayOfWeek.name.replaceFirstChar { if (it.isLowerCase()) it.titlecase() else it.toString() }

        return "Today is $dayOfWeekName, $monthName ${datetime.day}, ${datetime.year}"
    }

    fun convertLongToMb(sizeInBytes: Long): Double {
        if (sizeInBytes <= 0L) return 0.0
        return sizeInBytes / (1024.0 * 1024.0)
    }

    fun convertLongToReadableSize(
        sizeInBytes: Long,
        decimalPlaces: Int = 2,
    ): String {
        if (sizeInBytes < 0) return "Invalid size"
        if (sizeInBytes == 0L) return "0 b"

        val units = listOf("b", "kb", "mb", "gb", "tb", "pb", "eb")

        val digitGroups = floor(
            ln(sizeInBytes.toDouble()) / ln(1024.0)
        ).toInt()

        val value = sizeInBytes / 1024.0.pow(digitGroups)

        val formatted = value
            .toString()
            .let { raw ->
                val dotIndex = raw.indexOf('.')
                if (dotIndex == -1 || decimalPlaces == 0) {
                    raw.substringBefore('.')
                } else {
                    val endIndex = (dotIndex + 1 + decimalPlaces)
                        .coerceAtMost(raw.length)
                    raw.substring(0, endIndex)
                        .trimEnd('0')
                        .trimEnd('.')
                }
            }

        return "$formatted ${units[digitGroups]}"
    }


    fun generateUUID(
        maxLength: Int = 10,
        uuidStrength: UuidStrength = UuidStrength.SIMPLE
    ): String {

        val alphabets = ('A'..'Z') + ('a'..'z')
        val numbers = ('0'..'9')
        val symbols = listOf('-', '_', '@', '#', '$', '%')

        val timestamp = Clock.System.now().epochSeconds.toString()

        fun randomString(pool: List<Char>, length: Int): String =
            List(length) { pool.random() }.joinToString("")

        return when (uuidStrength) {

            UuidStrength.SIMPLE -> {
                // Timestamp-based, predictable but unique
                timestamp.takeLast(maxLength)
            }

            UuidStrength.MEDIUM -> {
                // Numbers + timestamp mix
                val base = timestamp + randomString(numbers.toList(), maxLength)
                base.take(maxLength)
            }

            UuidStrength.HARD -> {
                // Alphanumeric randomness
                val pool = alphabets + numbers
                randomString(pool, maxLength)
            }

            UuidStrength.TOUGH -> {
                // Alphanumeric + symbols + timestamp entropy
                val pool = alphabets + numbers + symbols
                randomString(pool, maxLength - 4) + timestamp.takeLast(4)
                    .toMutableList()
                    .shuffled()
                    .joinToString("")
                    .take(maxLength)
            }
        }
    }

    fun formatSrtTime(seconds: Double): String {
        val hours = (seconds / 3600).toInt()
        val minutes = ((seconds % 3600) / 60).toInt()
        val secs = (seconds % 60).toInt()
        val millis = ((seconds - seconds.toInt()) * 1000).toInt()

        return buildString {
            append(hours.toString().padStart(2, '0'))
            append(":")
            append(minutes.toString().padStart(2, '0'))
            append(":")
            append(secs.toString().padStart(2, '0'))
            append(",")
            append(millis.toString().padStart(3, '0'))
        }
    }

    fun bytesForSeconds(
        byteArray:ByteArray,
        seconds: Double = 10.0,
        totalDurationSeconds: Double
    ): ByteArray? {
        if (totalDurationSeconds <= 0) return null

        val bytesPerSecond = byteArray.size.toDouble() / totalDurationSeconds
        val targetSize = (bytesPerSecond * seconds).toInt()

        return byteArray.copyOfRange(
            fromIndex = 0,
            toIndex = minOf(targetSize, byteArray.size)
        )
    }

    fun bytesForSeconds(
        totalBytes: Int,
        seconds: Double,
        totalDurationSeconds: Double
    ): Int {

        if (seconds <= 0.0 || totalDurationSeconds <= 0.0) {
            return totalBytes
        }

        val bytesPerSecond =
            totalBytes.toDouble() / totalDurationSeconds

        return (bytesPerSecond * seconds).toInt()
    }


    /**
     * Converts a Long timestamp to a readable date and time string.
     * KMP-compatible using kotlinx-datetime
     *
     * @param timestamp Timestamp in milliseconds since epoch
     * @param pattern Format pattern (supports: yyyy, MM, dd, HH, mm, ss)
     * @param timeZone TimeZone (default: current system time zone)
     * @return Formatted date-time string
     */
    fun formatTimestamp(
        timestamp: Long,
        pattern: String = "yyyy-MM-dd HH:mm:ss",
        timeZone: TimeZone = TimeZone.currentSystemDefault()
    ): String {
        val instant = Instant.fromEpochMilliseconds(timestamp)
        val dateTime = instant.toLocalDateTime(timeZone)
        return formatDateTime(dateTime, pattern)
    }

    // Extension function for Long
    fun Long.toReadableDateTime(
        pattern: String = "yyyy-MM-dd HH:mm:ss",
        timeZone: TimeZone = TimeZone.currentSystemDefault()
    ): String = formatTimestamp(this, pattern, timeZone)

    // For seconds timestamp
    fun Long.toReadableDateTimeFromSeconds(
        pattern: String = "yyyy-MM-dd HH:mm:ss",
        timeZone: TimeZone = TimeZone.currentSystemDefault()
    ): String = formatTimestamp(this * 1000, pattern, timeZone)

    // Internal formatting function
    private fun formatDateTime(dateTime: kotlinx.datetime.LocalDateTime, pattern: String): String {
        return pattern
            .replace("yyyy", dateTime.year.toString().padStart(4, '0'))
            .replace("MM", dateTime.month.number.toString().padStart(2, '0'))
            .replace("dd", dateTime.day.toString().padStart(2, '0'))
            .replace("HH", dateTime.hour.toString().padStart(2, '0'))
            .replace("mm", dateTime.minute.toString().padStart(2, '0'))
            .replace("ss", dateTime.second.toString().padStart(2, '0'))
    }
}