package api.auth.kimdeo.screens.onboard

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import cafe.adriel.voyager.core.model.ScreenModel


enum class OnBoardScreenState{
    OnBoardingPage, FinalPage
}
class OnBoardingScreenModel : ScreenModel {
    var currentScreenPosition by mutableIntStateOf(1)
    var onBoardScreenState by mutableStateOf(OnBoardScreenState.OnBoardingPage)
        private set

    fun updateScreenState(screenState: OnBoardScreenState){
        onBoardScreenState = screenState
    }
    fun nextPage() {
        if (currentScreenPosition >= 3) return
        currentScreenPosition++
    }
    fun backPage() {
        if (currentScreenPosition <= 0) return
        currentScreenPosition--
    }
}