import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.material3.pulltorefresh.pullToRefresh
import androidx.compose.material3.pulltorefresh.rememberPullToRefreshState
import androidx.compose.runtime.Composable
import androidx.compose.runtime.produceState
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import api.auth.kimdeo.model.PopupModel
import api.auth.kimdeo.model.m_utils.ConnectionState
import api.auth.kimdeo.model.m_utils.GobackOrReload
import api.auth.kimdeo.model.m_utils.PulsingRing
import api.auth.kimdeo.model.m_utils.ShimmeringText
import api.auth.kimdeo.ui.DisplayPopup
import api.auth.kimdeo.ui.PixelDensity
import api.auth.kimdeo.ui.shimmerProgress
import api.auth.kimdeo.ui.verticalScrollable
import api.auth.kimdeo.utils.DeviceInfo
import api.auth.kimdeo.utils.Orientation
import api.auth.kimdeo.utils.rememberDeviceInfo
import cafe.adriel.voyager.core.model.rememberNavigatorScreenModel
import cafe.adriel.voyager.core.screen.Screen
import cafe.adriel.voyager.navigator.LocalNavigator
import cafe.adriel.voyager.navigator.currentOrThrow
import kotlinx.coroutines.delay

object KimdeoPlayerScreen : Screen {
    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val screenModel =
            LocalNavigator.currentOrThrow.rememberNavigatorScreenModel { KimdeoPlayerScreenModel() }
        Scaffold(
            modifier = Modifier
                .fillMaxSize(),
            bottomBar = {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {
                    TranscribeOutputPortrait(
                        modifier = Modifier.padding(PixelDensity.MEDIUM)
                            .fillMaxWidth()
                            .background(MaterialTheme.colorScheme.primaryContainer),
                        screenModel = screenModel
                    )
                }
            }) { pv ->
            when (screenModel.connectionState) {
                is ConnectionState.OnFailure -> {
                    Box(
                        Modifier.fillMaxSize().padding(pv),
                        contentAlignment = Alignment.Center
                    ) {
                        ShimmeringText(
                            shimmerColors = listOf(
                                MaterialTheme.colorScheme.error,
                                Color.Yellow,
                                MaterialTheme.colorScheme.onError,
                            ),
                            text = (screenModel.connectionState as ConnectionState.OnFailure).data
                        )
                    }
                }

                is ConnectionState.OnSucsess -> {
                    OnScreeModelSuccess(
                        modifier = Modifier.fillMaxSize()
                            .padding(pv), deviceInfo
                    )
                }

                else -> {
                    OnScreeModelInit(
                        Modifier.fillMaxSize().padding(pv),
                    )
                }
            }
        }
    }

    @Composable
    private fun OnScreeModelSuccess(modifier: Modifier, deviceInfo: DeviceInfo) {
        when (deviceInfo.orientation) {
            Orientation.PORTRAIT -> SelectVideoFilePortrait(
                modifier = modifier.then(
                    Modifier
                        .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.SMALL)
                        .verticalScrollable()
                )
            )

            else -> SelectVideoFileLandscape(
                modifier = modifier,
            )
        }
    }

    @Composable
    private fun OnScreeModelInit(
        modifier: Modifier,
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            val pulseBeforeShow = produceState(initialValue = false) {
                delay(5000)
                value = true
            }
            PulsingRing()
            if (pulseBeforeShow.value) {
                ShimmeringText(
                    modifier = Modifier.padding(top = PixelDensity.LARGE),
                    "Loading... seems to be taking a lot of time."
                )
            }
        }
    }

    @Composable
    internal fun KimPlayerPopup(screenModel: KimdeoPlayerScreenModel) {
        DisplayPopup(
            show = screenModel.displayTranscriptPopup.show,
            onDismiss = { screenModel.displayTranscriptPopup = PopupModel() },
            content = {
                Column(
                    modifier = Modifier.padding(PixelDensity.SMALL),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                ) {
                    Text(
                        text = screenModel.displayTranscriptPopup.title,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                    screenModel.displayTranscriptPopup.content()
                }
            }
        )
    }

    @Composable
    fun TranscribeOutputPortrait(modifier: Modifier, screenModel: KimdeoPlayerScreenModel) {
        Box(
            modifier,
            contentAlignment = Alignment.Center
        ) {
            Box(
                modifier = Modifier.fillMaxWidth()
                    .shimmerProgress(
                        color = MaterialTheme.colorScheme.primary,
                        shimmerColor = Color.Magenta,
                        progress = screenModel.transcribeProcess.first / 100
                    ).padding(PixelDensity.LARGE),
            )
            Text(
                text = screenModel.transcribeProcess.second.ifEmpty { "Transcription / Translation" },
                style = MaterialTheme.typography.bodyMedium.copy(
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSecondary
                )
            )
        }
    }
}
