    companion object {

        fun getCountryImageUrl(codeCountry: String): String {
//            return "https://flagsapi.com/${codeCountry.split("-").last()}/flat/64.png"
            return "https://flagcdn.com/32x24/${codeCountry.split("-").last().lowercase()}.png"
        }

        fun fromCodeCountry(codeCountry: String): KimLanguage? {
            return entries.find { it.codeCountry == codeCountry }
        }

        fun getDisplayName(language: KimLanguage): String {
            return language.langName
