class KimdeoPlayerScreenModel : ScreenModel {
    override fun onDispose() {
        super.onDispose()
        audioController?.stop()
        videoController?.stop()
        videoPlayerDisposable?.dispose()
        audioPlayerDisposable?.dispose()
        transcribeJobModel?.let {
            CoroutineScope(Dispatchers.Default).launch {
//                ApiActions.deleteJobByJobId(
//                    transcribeJobModel!!.transcriptionId,
//                )
                ApiActionsFile.deleteSpecificFiles(
                    delFilePath,
                    userModel?.email
                )
            }
        }
    }


    // This will hold our controller once the UI initializes
    var videoController: VideoInteraction? = null
        private set
    var audioController: AudioInteraction? = null
        private set
    var videoPlayerDisposable: Disposable? = null
    var audioPlayerDisposable: Disposable? = null
    var displayTranscriptPopup by mutableStateOf(PopupModel())
    var availableSubPopup by mutableStateOf(PopupModel())
    var connectionState by mutableStateOf<ConnectionState>(ConnectionState.None)
        private set
//    var fileUploadState by mutableStateOf<FileConnectionState>(FileConnectionState.None)

    var transcribeProcess by mutableStateOf(Triple(0f, "", ""))
        private set
    var transcribeJobModel: TranscribeJobModel? = null
    private val _transcribeJobModels = mutableStateListOf<TranscribeJobModel>()
    val transcribeJobModels: List<TranscribeJobModel> get() = _transcribeJobModels

    val audioFilePaths = mutableListOf<FilePathModel>()
    var audioFilePath: FilePathModel? = null
    var audioPosition = 0
    var loadingNextAudio = false
        private set
    var lastSeekTime = 0.0
//    var audioFilePathNext: FilePathModel? = null

    var kimLanguage by mutableStateOf(KimLanguage.ENGLISH)
    private var _kimLanguages =
        mutableStateListOf<KimLanguage>().apply { addAll(KimLanguage.entries.shuffled().take(5)) }
    val kimLanguages: List<KimLanguage> get() = _kimLanguages

    var fileByteArray by mutableStateOf<ByteArray?>(null)
        private set
    var audioByteArray by mutableStateOf<ByteArray?>(null)
        private set
    private val delFilePath = mutableListOf<String>()
    var platformFile by mutableStateOf<PlatformFile?>(null)
    val userToken = PreferenceManager.getUserToken()
    var userModel by mutableStateOf<UserModel?>(null)
    val selectedTranscribeJobModels: List<TranscribeJobModel>
        get() {
            val file = platformFile?.name?.normalizeName()
            return transcribeJobModels.filter { tm ->
                val subtitle = tm.filePath.normalizeName()
                file != null && subtitle.contains(file)
            }
        }


    init {
        resetScreenModel()
    }

    fun resetScreenModel() {
        screenModelScope.launch {
            connectionState = ConnectionState.OnLoading
            if (userToken != null) {
                val u = ApiActions.getUserModelByEmail(userToken.email)
                if (u.data == null) {
                    return@launch
                }
                userModel = u.data
                val tm = ApiActions.getJobs(u.data.email)
                _transcribeJobModels.addAll(tm.data?.filter { it.filePaths.isNotEmpty() }
                    ?: emptyList())
            }
            connectionState = if (userModel == null) {
                ConnectionState.OnFailure("User not found or could not be loaded")
            } else {
                ConnectionState.OnSucsess("")
            }
        }
    }

    fun attachVideoController(
        controller: VideoInteraction
    ) {
        videoController = controller
    }

    fun updateTranscribeModel(tjm: TranscribeJobModel) {
        screenModelScope.launch {
            audioFilePaths.clear()
            audioFilePaths.addAll(tjm.filePaths)
            audioFilePath = audioFilePaths.first()
            audioByteArray = ApiActionsFile.loadFile(
                audioFilePath?.filePath,
                userModel?.userId ?: ""
            )
//            audioFilePathNext = audioFilePaths.last()
//            audioByteArrayNext = ApiActionsFile.loadFile(
//                audioFilePathNext?.filePath,
//                userModel?.userId ?: ""
//            )
        }
        transcribeJobModel = tjm
        availableSubPopup = PopupModel()
    }

    fun attachAudioController(
        controller: AudioInteraction
    ) {
        audioController = controller
    }

    fun checkKimLanguages(lang: String) {
        if (lang.isBlank()) {
            _kimLanguages.clear()
            _kimLanguages.addAll(KimLanguage.entries.shuffled().take(5))
            return
        }
        // 1. Calculate the new data first
        val filtered = KimLanguage.entries
            .filter {
                val name = it.name.lowercase()
                name.contains(lang.lowercase(), ignoreCase = true)
            }
            .shuffled()
            .take(5)

        // 2. Update the existing SnapshotStateList
        _kimLanguages.clear()
        _kimLanguages.addAll(filtered)
    }

    fun getMediaFile() {
        screenModelScope.launch(Dispatchers.Main) {
            platformFile = FileKit.openFilePicker(
                mode = FileKitMode.Single,
                type = FileKitType.File(ExportVideoFormat.entries.map { it.name.lowercase() }
                    .toSet())
            )
            fileByteArray = platformFile?.readBytes()
//            fileByteArray = platformFile?.readBytes()
//            fileUploadState =
//                if (platformFile == null) FileConnectionState.None else FileConnectionState.OnGotten(
//                    "Selected media file was ${platformFile?.name}"
//                )
        }
    }


    fun transcribeVideo() {
        screenModelScope.launch {
            transcribeJobModel = null
            val fileBytes = platformFile?.size()
            runCatching {
                ApiActions.createVoicePlayer(
                    email = userModel!!.email,
                    fileName = platformFile!!.name,
                    languageCode = kimLanguage.codeCountry,
                    bytes = platformFile!!.readBytes(),
                    mimeType = platformFile?.mimeType()?.toString() ?: "application/octet-stream",
                    onProgress = { sentByte ->
                        transcribeProcess = if (fileBytes == null) Triple(0f, "", "")
                        else Triple(
                            fileBytes.toPercentage(sentByte).toFloat(),
                            "uploading file ${
                                Tools.convertLongToReadableSize(sentByte).replace("b", "%")
                            } of ${
                                Tools.convertLongToReadableSize(platformFile!!.size())
                            }",
                            ""
                        )
                    },
                )
            }
                .onSuccess { response ->
                    if (response.data != null) {
                        transcribeJobModel = response.data
                        ApiActionsWebsocket.connectToPlayerWebsocket(
                            response.data.transcriptionId,
                            userModel?.apiKey!!,
                            onConnect = { t ->
                                transcribeJobModel = t
//                                audioFilePaths.clear()
                                audioFilePaths.addAll(t.filePaths)
                                if (transcribeJobModel!!.jobStatus == JobStatus.COMPLETED) {
                                    _transcribeJobModels.replaceAllWhere { if (it.transcriptionId == t.transcriptionId) t else it }
                                }
                                transcribeProcess = Triple(
                                    t.completePercent.toFloat(),
                                    t.message,
                                    ""
                                )
                            }
                        )
                        audioFilePath = transcribeJobModel?.filePaths?.first()
                        audioByteArray = ApiActionsFile.loadFile(
                            audioFilePath?.filePath,
                            userModel?.userId ?: ""
                        )
                        Logger.e { "audioFilePath : $audioFilePath" }
//                        audioFilePathNext = transcribeJobModel?.filePaths?.last()
                    } else {
                        transcribeProcess = Triple(
                            0f,
                            "File upload and transcription failed",
                            ""
                        )
                    }
                }
                .onFailure { error ->
                    transcribeProcess = Triple(
                        0f,
                        error.message ?: "There was an error uploading file",
                        ""
                    )
                    displayTranscriptPopup = PopupModel(
                        show = true, title = "", content =
                            {
                                HorizontalTextIcon(
                                    leadingContent = {
                                        Icon(
                                            TablerIcons.AlertTriangle,
                                            null,
                                            tint = Color.Red
                                        )
                                    },
                                    text = error.message
                                        ?: "There was an error processing video file"
                                )
                            })
                    Logger.e { "Player Error : $error" }
                }
        }
    }

    fun onWatchVideoClicked(function: () -> Unit) {
        function()
    }


    @OptIn(ExperimentalCoroutinesApi::class)
    fun updatePlayingAudio(audioPos: FilePathModel? = null) {
        if (audioFilePath == null || audioByteArray == null) return
        screenModelScope.launch {
            loadingNextAudio = true
            if (audioPos == null) {
                audioPosition++
                audioFilePath = audioFilePaths[audioPosition]
            } else {
                audioFilePath = audioPos
            }
            audioController?.stop()
            audioPlayerDisposable?.dispose()
            audioByteArray = ApiActionsFile.loadFile(
                audioFilePath?.filePath,
                userModel?.userId ?: ""
            )
            audioPlayerDisposable = loadHiddenAudioMetadata(
                bytes = audioByteArray!!,
                mimeType = "audio/wav",
                onReady = { interaction ->
                    attachAudioController(interaction)
                }
            )

            ApiActionsWebsocket.connectToPlayingVideoWebsocket(
                jobId = transcribeJobModel?.transcriptionId,
                userApikey = userModel?.apiKey,
                onConnect = { fpm ->
                    fpm?.let {
                        audioFilePaths.add(it)
                        it.filePath?.let { element -> delFilePath.add(element) }
                    }
                },
                genVoice = GenerateVoiceWVIPModel(
                    email = userModel!!.email,
                    jsonFilePath = transcribeJobModel!!.mediaJsonPath,
                    jobId = transcribeJobModel!!.transcriptionId,
                    languageCode = kimLanguage.codeCountry,
                    startTime = audioFilePath!!.endTime
                )
            )
            loadingNextAudio = false
        }
    }

    internal fun onBackPressed(function: () -> Unit) {
        audioController?.stop()
        function()
        screenModelScope.launch {
            ApiActionsFile.deleteSpecificFiles(
                delFilePath,
                userModel?.email
            )
        }
    }
}